        "Gravity Feeder with Agitator",
        "Screw Feeder",
        "Belt Feeder",
        "Vibratory Feeder",
        "Cone Feeder"
      ],
      "alternatives": "OR",
      "characteristics": {
        "note": "Any other type of feeding device may also be used."
      }
    },
    {
      "role": "weighing_unit",
      "type_designations": [],
      "alternatives": null,
